    function hf_icon($name, $size = 24, $class = '')
    {
        $p = hf_icon_paths();
        if (!isset($p[$name])) {
            return '';
        }
        return '<svg class="hf-i' . ($class ? ' ' . $class : '') . '" viewBox="0 0 24 24" width="' . (int) $size . '" height="' . (int) $size . '" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $p[$name] . '</svg>';
    }
    // $max: use the site's translation only when it is short enough for a tile label
    function hf_t($key, $fallback, $max = 0)
    {
        global $wo;
        if (empty($wo['lang'][$key])) {
            return $fallback;
        }
        $v = $wo['lang'][$key];
        if ($max > 0 && function_exists('mb_strlen') && mb_strlen($v) > $max) {
            return $fallback;
        }
        return $v;
    }
}
if (!function_exists('hf_admin_url')) {
    function hf_admin_url()
    {
        global $wo;
        return $wo['config']['site_url'] . '/admin-cp';
    }
